"""Read-only local monitoring. No order/control endpoints."""
from aiohttp import web
from .models import canonical
PAGE='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trading V1 · Research paper</title><style>body{font:15px system-ui;color:#18283f;background:#f2f5fa;max-width:1200px;margin:30px auto;padding:16px}section{padding:20px;border-radius:12px;background:white;margin:18px 0}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{text-align:left;padding:7px;border-bottom:1px solid #edf0f6}.scroll{max-height:350px;overflow:auto}code{font-size:12px}.warn{color:#9b4c00}</style><h1>Trading V1 · Только виртуальные счета</h1><p class="warn">Исследовательский эксперимент R1. Результат не подтверждает OOS edge. Реальные ордера отсутствуют.</p><p id="status">Загрузка…</p><section><h2>Виртуальные счета</h2><div class="scroll"><table id="accounts"></table></div></section><section><h2>Агенты и задержки</h2><div class="scroll"><table id="agents"></table></div></section><section><h2>Допуск гипотез</h2><div class="scroll"><table id="registry"></table></div></section><section><h2>Позиции, цели и ошибки</h2><pre id="detail" style="white-space:pre-wrap"></pre></section><script>const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function table(id,headers,rows){document.getElementById(id).innerHTML='<tr>'+headers.map(x=>'<th>'+escape(x)+'</th>').join('')+'</tr>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+escape(x)+'</td>').join('')+'</tr>').join('')}async function update(){try{const r=await fetch('/api/state',{cache:'no-store'}),s=await r.json(),e=s.engine;document.getElementById('status').textContent=s.status+' · '+Object.keys(s.agents).length+' агентов · '+s.fresh_batches+' новых / '+s.recovered_batches+' восстановленных минут · '+new Date(e.now).toISOString();table('accounts',['Счёт','Cash','Equity','Realized','Unrealized','Комиссии','Max DD','Защита'],Object.entries(e.accounts).map(([id,a])=>[id,a.cash,a.equity,a.realized_pnl,s.account_metrics[id]?.unrealized_pnl||'0',s.account_metrics[id]?.fees||'0',(Number(a.max_dd)*100).toFixed(3)+'%',a.state]));table('agents',['Агент','Состояние','Вызовы','Ошибки','Задержка,мс'],Object.entries(s.agents).map(([id,a])=>[id,a.status,a.calls,a.errors,Number(a.latency_ms).toFixed(2)]));table('registry',['Гипотеза','Уровень','Режимы','Причина'],s.registry.map(r=>[r.hypothesis_id,r.level,r.modes.join(', '),r.reason||'']));document.getElementById('detail').textContent=JSON.stringify({pending_orders:e.pending_orders,positions:Object.fromEntries(Object.entries(e.accounts).filter(([id,a])=>Object.values(a.positions).some(p=>Number(p.quantity)>0)).map(([id,a])=>[id,a.positions])),errors:s.errors,blocked:s.blocked},null,2)}catch(e){document.getElementById('status').textContent='STALE — heartbeat недоступен; работа процесса не подтверждена: '+e}}update();setInterval(update,5000)</script></html>'''
async def serve(runtime,port=8765):
    async def home(request):return web.Response(text=PAGE,content_type='text/html',headers={'Cache-Control':'no-store'})
    async def state(request):return web.Response(text=canonical(runtime.snapshot()),content_type='application/json',headers={'Cache-Control':'no-store'})
    app=web.Application();app.router.add_get('/',home);app.router.add_get('/api/state',state)
    runner=web.AppRunner(app);await runner.setup();await web.TCPSite(runner,'127.0.0.1',port).start();return runner
